const D = { scale:1, density:.55, energy:.6, speed:1, hue:35, x:.5, y:.5, seed:0, style:'1bit', act:'boil' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const TAU = 6.28318530718, cl = (v,a,b)=>v<a?a:v>b?b:v;
const fr = i=>{ const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };

// ---- working buffer keyed on aspect bucket ----
const asp = width/height;
const LS = 180;
let bw, bh;
if (asp>=1){ bw=LS; bh=Math.max(8,Math.round(LS/asp)); } else { bh=LS; bw=Math.max(8,Math.round(LS*asp)); }
const bkey = bw+'x'+bh;
if (!S.buf || S.bkey!==bkey){ if (S.buf && S.buf.remove) S.buf.remove(); S.buf = createGraphics(bw,bh); S.buf.pixelDensity(1); S.bkey = bkey; }
const g = S.buf;

// ---- 8x8 Bayer ----
if (!S.bay){
  const b=[0,32,8,40,2,34,10,42,48,16,56,24,50,18,58,26,12,44,4,36,14,46,6,38,60,28,52,20,62,30,54,22,3,35,11,43,1,33,9,41,51,19,59,27,49,17,57,25,15,47,7,39,13,45,5,37,63,31,55,23,61,29,53,21];
  const bb=new Float32Array(64); for (let i=0;i<64;i++) bb[i]=(b[i]+.5)/64; S.bay=bb;
}

// ---- seeded wave field ----
const nW=4;
if (S.seedUsed!==P.seed){
  S.seedUsed=P.seed; const W=[]; let sw=0;
  for (let i=0;i<nW;i++){
    const ang=fr(i*9)*TAU, f=1.2+fr(i*9+1)*3.5, w=.6+fr(i*9+5)*.6;
    W.push({ fx:Math.cos(ang)*f, fy:Math.sin(ang)*f, ph:fr(i*9+2)*TAU, sp:(fr(i*9+3)*.8+.3)*(fr(i*9+4)<.5?-1:1), w:w });
    sw+=w;
  }
  S.W=W; S.sumW=sw;
}

// ---- ink/paper palette keyed style+hue ----
const style=P.style, hue=cl(P.hue,0,360);
const ckey=style+'|'+Math.round(hue);
if (S.ckey!==ckey){
  S.ckey=ckey;
  const rgb=(h,s,b)=>{ const c=color(h,s,b); return [c.levels[0],c.levels[1],c.levels[2]]; };
  if (style==='amber'){ S.ink=rgb(hue||35,92,96); S.pap=rgb(30,80,5); }
  else if (style==='blueprint'){ S.pap=rgb(212,78,26); S.ink=rgb(200,16,96); }
  else if (style==='newsprint'){ S.pap=rgb(44,14,92); S.ink=rgb(0,0,9); }
  else if (style==='xray'){ S.pap=rgb(216,60,5); S.ink=rgb(205,12,97); }
  else if (style==='thermal'){ const hp=[[240,90,20],[210,90,55],[300,70,60],[10,90,75],[45,95,96]]; S.heat=hp.map(a=>rgb(a[0],a[1],a[2])); }
  else { S.pap=rgb(0,0,95); S.ink=rgb(0,0,7); }
}

// ---- per-frame field params ----
const spd=cl(P.speed,.2,4), en=cl(P.energy,0,1), sc=cl(P.scale,.3,3);
const freqScale = .5 + sc*1.1;
const cover = cl(P.density,0,1);
const bias = (cover-.5)*.9;
const contrast = .7 + en*1.6;
const pump = K.pulse*.05*en + (A.rms||0)*.22 + (A.bass||0)*.1;
const drift = P.act==='drift' ? K.t*spd*.06 : 0;
const ripple = P.act==='ripple';
const rf = 8 + sc*6;
const rph = K.t*spd*2;
const W=S.W, bay=S.bay;
const norm = .5 / (S.sumW + (ripple?.9:0));
const px0 = cl(P.x,0,1), py0 = cl(P.y,0,1);

// ---- render dither ----
g.loadPixels();
const px=g.pixels, invW=1/(bw-1), invH=1/(bh-1);
const ink=S.ink, pap=S.pap, heat=S.heat;
let idx=0;
for (let yy=0; yy<bh; yy++){
  const ny=yy*invH, row=(yy&7)*8;
  for (let xx=0; xx<bw; xx++){
    const nx=xx*invW, ax=nx+drift;
    let raw=0;
    for (let i=0;i<nW;i++){ const w=W[i]; raw += Math.sin(ax*w.fx*freqScale + ny*w.fy*freqScale + w.ph + K.t*spd*w.sp)*w.w; }
    if (ripple){ const dx=(nx-px0)*asp, dy=ny-py0; const d=Math.sqrt(dx*dx+dy*dy); raw += Math.sin(d*rf - rph)*.9; }
    let f = .5 + raw*norm;
    f = .5 + (f-.5)*contrast + bias + pump;
    if (f<0) f=0; else if (f>1) f=1;
    const th = bay[row + (xx&7)];
    let r,gg,bb2;
    if (style==='thermal'){
      let q = f + (th-.5)/5; if (q<0) q=0; else if (q>.999) q=.999;
      const lvl=(q*5)|0; const c=heat[lvl]; r=c[0]; gg=c[1]; bb2=c[2];
    } else {
      const c = f>th ? ink : pap; r=c[0]; gg=c[1]; bb2=c[2];
    }
    px[idx]=r; px[idx+1]=gg; px[idx+2]=bb2; px[idx+3]=255; idx+=4;
  }
}
g.updatePixels();

drawingContext.imageSmoothingEnabled = false;
image(g,0,0,width,height);
drawingContext.imageSmoothingEnabled = true;
blendMode(BLEND);
